#include <vector>
#include <stdexcept>

struct ThrowingCopy {
    int val;
    ThrowingCopy(int v) : val(v) {}
    ThrowingCopy(const ThrowingCopy& other) : val(other.val) {
        // If this throws during vector reallocation, the guarantee fails.
        if (other.val == 5) {
            // throw std::runtime_error("Copy failed!");
        }
    }
};

int main() {
    // std::vector<ThrowingCopy> v; 
    // v.reserve(10);
    // v.push_back(ThrowingCopy(5)); // If copy throws, state may be corrupted

    // Better: Ensure element properties support strong safety:
    // Requires C++11 or later move semantics and noexcept guarantees.
    struct NoThrowCopy {
        int val;
        NoThrowCopy(const NoThrowCopy&) = default;
        // Ensure move constructor is noexcept (often default)
        NoThrowCopy(NoThrowCopy&&) noexcept = default;
    };
    std::vector<NoThrowCopy> safe_v;
}
